/* M1 staging integration (progressive enhancement).
   Demo mode (default, incl. production): pure fictional data, unchanged.
   Live mode: signed-in staff session against same-origin /api (staging only).
   Live and demo records are never mixed, and live records are never stored locally. */
let live=null,liveClients=[];
async function api(path,opts){
  const r=await fetch(path,Object.assign({credentials:'same-origin',headers:{'Content-Type':'application/json'}},opts||{}));
  let j=null;try{j=await r.json()}catch(e){}
  return {ok:r.ok,st:r.status,j:j};
}
async function refreshLiveClients(){
  try{
    const c=await api('/api/v1/staff/clients');
    if(c.ok&&c.j&&Array.isArray(c.j.data)){liveClients=c.j.data;return true}
  }catch(e){}
  return false;
}
async function probeSession(){
  try{
    const m=await api('/api/v1/me');
    if(!m.ok||!m.j||!m.j.data||!m.j.data.user)return false;
    const roles=m.j.data.roles||[];
    if(roles.indexOf('administrator')<0&&roles.indexOf('dietitian')<0)return false;
    if(!await refreshLiveClients())return false;
    live={email:m.j.data.user.email,roles:roles};
    return true;
  }catch(e){return false}
}
async function openLiveClient(id){
  try{
    const r=await api('/api/v1/staff/clients/'+encodeURIComponent(id));
    if(!r.ok||!r.j||!r.j.data){toast('Could not load customer record.','No se pudo cargar el expediente.');return}
    ui.liveDetail=r.j.data;ui.detail=null;ui.modal=null;paint();
  }catch(e){toast('Could not load customer record.','No se pudo cargar el expediente.')}
}
function liveClientsPage(){
  const q=(ui.search||'').toLowerCase();
  const items=liveClients.filter(c=>((c.display_name||'')+' '+c.email).toLowerCase().indexOf(q)>=0);
  const canCreate=!!(live&&live.roles.indexOf('administrator')>=0);
  return `${head(B('PEOPLE & RELATIONSHIPS','PERSONAS Y RELACIONES'),B('Your clients','Tus clientes'),B('Live staging records from the shared database. Demo data is hidden while signed in.','Registros reales de staging desde la base compartida. Los datos ficticios estan ocultos mientras haya sesion.'),canCreate?uiButton('staff-new-client',B('Add customer','Agregar cliente'),'','','plus'):`<span class="muted small">${B('Read-only: administrators can add customers.','Solo lectura: solo administradores agregan clientes.')}</span>`)}<section class="card card-pad"><div class="filterbar"><label class="search">${i('search')}<input id="client-search" type="search" autocomplete="off" placeholder="${B('Search name or email','Buscar nombre o correo')}" value="${escapeHTML(ui.search)}" aria-label="${B('Search clients','Buscar clientes')}"></label><span class="muted small">${items.length} ${B('record(s)','registro(s)')}</span></div><div class="table-wrap"><table class="table"><thead><tr><th>${B('Customer','Cliente')}</th><th>${B('Display name','Nombre')}</th><th>${B('Language','Idioma')}</th><th>${B('Since','Desde')}</th><th></th></tr></thead><tbody>${items.map(c=>{const nm=c.display_name||c.email;return `<tr><td><div class="client-cell"><span class="initials">${initials(nm)}</span><span><strong>${escapeHTML(nm)}</strong><small>${escapeHTML(c.email)}</small></span></div></td><td>${escapeHTML(c.display_name||'--')}</td><td>${escapeHTML((c.locale||'').toUpperCase())}</td><td>${escapeHTML((c.created_at||'').slice(0,10))}</td><td><button class="link-btn" data-action="client" data-id="${c.id}">${B('Open profile','Ver perfil')} ${i('chevron')}</button></td></tr>`}).join('')||`<tr><td colspan="5" class="empty">${B('No customers yet.','Aun no hay clientes.')}</td></tr>`}</tbody></table></div></section><div class="notice mt">${i('shield')}<div>${B('Live staging data. Plans, credits and history connect in M4/M5; menu, credits and status columns stay blank until then.','Datos reales de staging. Planes, creditos e historial llegan en M4/M5; esas columnas siguen vacias hasta entonces.')}</div></div>`}
function liveClientDrawer(c){
  const h=c.household||{};
  const nm=c.display_name||c.email;
  const ent=Array.isArray(c.entitlements)?c.entitlements:[];
  const row=(k,v)=>`<dt>${k}</dt><dd>${v}</dd>`;
  return `<div class="backdrop" data-action="close-modal"><section role="dialog" aria-modal="true" aria-label="${B('Client profile','Perfil del cliente')}" class="drawer" data-stop><div class="drawer-head"><div class="flex" style="gap:12px"><span class="initials" style="width:50px;height:50px;font-size:19px">${initials(nm)}</span><div><h2>${escapeHTML(nm)}</h2><p>${escapeHTML(c.email)}</p></div></div><button class="icon-btn" data-action="close-modal" aria-label="Close">${i('close')}</button></div><div class="flex"><span class="pill neutral">LIVE</span><span class="pill neutral">${escapeHTML((c.locale||'').toUpperCase())}</span></div><dl class="inline-details">${row(B('Display name','Nombre'),escapeHTML(c.display_name||'--'))}${row(B('Program','Programa'),ent.length?escapeHTML(ent.map(e=>e.kind).join(', ')):B('No active program yet','Sin programa activo'))}${row(B('Household','Hogar'),escapeHTML(String(h.household_size!=null?h.household_size:'--'))+' '+B('people','personas'))}${row(B('Cooking comfort','Nivel de cocina'),escapeHTML(h.skill||'--'))}${row(B('Cooking time','Tiempo disponible'),h.cooking_minutes!=null?h.cooking_minutes+' min':'--')}${row(B('Store preference','Tienda preferida'),escapeHTML(h.store||'--'))}${row(B('Delivery','Entregas'),escapeHTML(h.delivery_cadence||'--'))}${row(B('Customer since','Cliente desde'),escapeHTML((c.created_at||'').slice(0,10)))}</dl><div class="notice mt">${i('shield')}<div>${B('Live staging record from the shared database. Menu plans, credit ledger and message history connect in M4/M5.','Expediente real de staging desde la base compartida. Menus, creditos e historial llegan en M4/M5.')}</div></div></section></div>`;
}
function staffLoginModal(){return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Staff sign in','Acceso del equipo')}" data-stop>${modalHeader(B('Staff sign in (staging)','Acceso del equipo (staging)'),B('Signs into the shared staging database. Production has no sign-in.','Inicia sesion en la base compartida de staging. Produccion no tiene acceso.'))}<form id="staff-login-form"><div class="form-grid"><div class="form-field"><label>Email</label><input name="email" type="email" required autocomplete="username"></div><div class="form-field"><label>${B('Password','Contrasena')}</label><input name="password" type="password" required autocomplete="current-password"></div></div><div class="modal-actions"><button class="btn ghost" type="button" data-action="close-modal">${B('Cancel','Cancelar')}</button><button class="btn" type="submit">${B('Sign in','Entrar')}</button></div></form></section></div>`}
function staffClientModal(){return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Add customer','Agregar cliente')}" data-stop>${modalHeader(B('Add a staging customer','Agregar cliente de staging'),B('Creates a real account in the staging database only. Share credentials securely.','Crea una cuenta real solo en la base de staging. Comparte el acceso por un canal seguro.'))}<form id="staff-client-form"><div class="form-grid"><div class="form-field"><label>Email</label><input name="email" type="email" required autocomplete="off"></div><div class="form-field"><label>${B('Temporary password (10+ chars)','Contrasena temporal (10+ caracteres)')}</label><input name="password" type="password" required minlength="10" maxlength="128" autocomplete="new-password"></div><div class="form-field"><label>${B('Display name','Nombre')}</label><input name="name" maxlength="120" autocomplete="off"></div></div><div class="modal-actions"><button class="btn ghost" type="button" data-action="close-modal">${B('Cancel','Cancelar')}</button><button class="btn" type="submit">${B('Create account','Crear cuenta')}</button></div></form></section></div>`}
const ui={page:'overview',menuOpen:false,modal:null,detail:null,detailTab:'profile',filter:'all',search:'',planFilter:'review',apptFilter:'upcoming',messageId:'m1',recipeFilter:'all',groceryFilter:'open',creditClient:'c1'};
const client=id=>data.clients.find(c=>c.id===id)||null;const recipe=id=>recipes.find(r=>r.id===id)||recipes[0];const holds=id=>data.appointments.filter(a=>a.client===id&&a.status==='scheduled'&&a.type==='paid').reduce((s,a)=>s+Math.ceil(a.duration/30),0);const available=c=>Math.max(0,c.credits-holds(c.id));
const statusLabel=s=>({active:B('Active','Activo'),ending:B('Ending soon','Por finalizar'),paused:B('Paused','Pausado'),review:B('Needs approval','Por aprobar'),approved:B('Approved','Aprobado'),revision:B('Needs revision','Requiere cambios'),open:B('Open','Abierto'),resolved:B('Resolved','Resuelto'),scheduled:B('Scheduled','Programada'),completed:B('Completed','Completada'),cancelled:B('Cancelled','Cancelada')})[s]||s;
const statusPill=s=>`<span class="pill ${['ending','review','open'].includes(s)?'warn':['paused','cancelled','revision'].includes(s)?'red':['approved','completed','resolved'].includes(s)?'':'neutral'}">${escapeHTML(statusLabel(s))}</span>`;
const person=id=>{let c=client(id);return c?escapeHTML(c.name):B('Unknown customer','Cliente desconocido')};
const initials=name=>name.split(' ').slice(0,2).map(n=>n[0]).join('');
const pages=()=>[['overview','home',B('Overview','Resumen')],['clients','users',B('Clients','Clientes')],['plans','chef',B('Menu approvals','Aprobación de menús')],['recipes','book',B('Recipe library','Recetario')],['appointments','calendar',B('Consultations','Consultas')],['credits','wallet',B('Credits','Créditos')],['services','heart',B('Services','Servicios')],['messages','message',B('Messages','Mensajes')],['groceries','basket',B('Grocery reviews','Revisión de compras')],['settings','settings',B('Settings','Configuración')]];
const pageName=()=>pages().find(p=>p[0]===ui.page)?.[2]||'Overview';
const uiButton=(action,txt,kind='',args='',iconName='')=>`<button type="button" class="btn ${kind}" data-action="${action}" ${args}>${iconName?i(iconName):''}${txt}</button>`;
const head=(kicker,title,subtitle,actions='')=>`<header class="head"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${subtitle}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</header>`;
const cardTitle=(title,subtitle,action='')=>`<div class="section-head"><div><h2>${title}</h2>${subtitle?`<p>${subtitle}</p>`:''}</div>${action}</div>`;
const numberCount=(key)=>{if(key==='plans')return data.plans.filter(p=>p.status==='review').length;if(key==='messages')return data.messages.filter(m=>m.unread&&!m.closed).length;if(key==='groceries')return data.groceries.filter(g=>g.status==='open').length;return 0};
function shell(){return `<div class="mobile-overlay ${ui.menuOpen?'open':''}" data-action="close-menu"></div><div class="shell"><aside class="sidebar ${ui.menuOpen?'open':''}" id="sidebar"><a class="brand" href="/" aria-label="Nutri Chapina website"><img src="./assets/leaf.svg" alt=""><span>Nutri Chapina</span></a><div class="admin-mark">${B('Practice console','Consola profesional')}</div><div class="nav-label">${B('YOUR WORKSPACE','TU ESPACIO DE TRABAJO')}</div><nav class="nav-list" aria-label="${B('Admin navigation','Navegación de administración')}">${pages().map(([key,icon,title])=>`<button type="button" class="nav-btn ${ui.page===key?'active':''}" data-action="navigate" data-id="${key}" aria-current="${ui.page===key?'page':'false'}">${i(icon)}<span>${title}</span>${numberCount(key)?`<span class="nav-count">${numberCount(key)}</span>`:''}</button>`).join('')}</nav><div class="sidebar-spacer"></div><div class="side-box"><div class="eyebrow">${B('CARE FIRST','PRIMERO LAS PERSONAS')}</div><strong>${B('Behind every plan is a person.','Detrás de cada plan hay una persona.')}</strong><p>${B('Make time for the clients who need your attention most.','Dedica tiempo a quienes más necesitan tu atención.')}</p></div><div class="side-foot"><a href="/dashboard">${B('Customer dashboard','Portal de clientes')} →</a><a href="/">${B('Back to website','Volver al sitio web')} →</a><button type="button" data-action="reset" style="background:none;border:0;text-align:left;text-decoration:underline;font-size:11px;color:#63765d;padding:0">${B('Reset sample data','Restablecer datos de prueba')}</button></div></aside><div class="main"><div class="top"><div class="flex"><button class="hamburger" type="button" aria-label="${B('Open menu','Abrir menú')}" data-action="toggle-menu">${i('menu')}</button><div class="breadcrumbs">Nutri Chapina <span>›</span><b>${pageName()}</b></div></div><div class="top-actions">${live?`<span class="tag-demo">${B('LIVE - STAFF SESSION','EN VIVO - SESION DEL EQUIPO')}</span><span class="tag-demo">${escapeHTML(live.email)}</span><button type="button" class="link-btn" data-action="staff-logout">${B('Sign out','Cerrar sesion')}</button>`:`<span class="tag-demo">${B('STAFF DEMO · SAMPLE DATA','DEMO INTERNA · DATOS FICTICIOS')}</span><button type="button" class="link-btn" data-action="staff-login">${B('Staff sign in','Acceso del equipo')}</button>`}<div class="lang" role="group" aria-label="Language"><button data-action="language" data-id="en" aria-pressed="${lang==='en'}">EN</button><button data-action="language" data-id="es" aria-pressed="${lang==='es'}">ES</button></div><span class="circle-avatar" title="Demo dietitian">N</span></div></div><main class="body" id="main-content">${renderPage()}<div class="dashboard-footer"><b>${B('Interactive staff demo','Demo interactiva para el equipo')}</b> · ${B('Fictional customers and in-memory changes only. No appointments, menu approvals, charges, messages, or grocery orders are submitted. Do not enter real client or clinical information.','Clientes ficticios y cambios solo en esta sesión. No se envían citas, aprobaciones de menús, cobros, mensajes ni pedidos. No ingreses información clínica real.')}</div></main></div></div>${modalMarkup()}<div id="toast" role="status" aria-live="polite"></div>`}
function overview(){const pending=data.plans.filter(p=>p.status==='review');const unread=data.messages.filter(m=>m.unread&&!m.closed);const upcoming=data.appointments.filter(a=>a.status==='scheduled').sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));const alerts=[{icon:'chef',title:B('Menus waiting for review','Menús pendientes de revisión'),sub:B(`${pending.length} proposed plans need a decision`,`${pending.length} planes propuestos esperan decisión`),page:'plans',num:pending.length},{icon:'message',title:B('Customers waiting for a response','Clientes esperando respuesta'),sub:B(`${unread.length} new conversations`,`${unread.length} conversaciones nuevas`),page:'messages',num:unread.length},{icon:'basket',title:B('Grocery list exceptions','Detalles por resolver en compras'),sub:B(`${data.groceries.filter(g=>g.status==='open').length} items need attention`,`${data.groceries.filter(g=>g.status==='open').length} productos necesitan revisión`),page:'groceries',num:1}];return `<section class="hero card"><div class="hero-copy"><div class="eyebrow">${B('SUNDAY · NOVEMBER 22, 2026','DOMINGO · 22 DE NOVIEMBRE DE 2026')}</div><h1>${B('A thoughtful practice, beautifully organized.','Una atención cercana, bien organizada.')}</h1><p class="subtitle">${B('One calm place to care for your clients, review their menus, and manage your time.','Un solo lugar para atender a tus clientes, revisar sus menús y organizar tus consultas.')}</p></div><div class="hero-stamp"><strong>${data.clients.filter(c=>c.status==='active').length}</strong><span>${B('active customer relationships','clientes activos')}</span></div></section><div class="metric-grid">${[[B('Active clients','Clientes activos'),data.clients.filter(c=>c.status==='active').length,B('Currently enrolled','Inscritos actualmente'),'users'],[B('Menus to review','Menús por revisar'),pending.length,B('Including flagged plans','Incluye planes con alertas'),'chef'],[B('Upcoming sessions','Próximas consultas'),upcoming.length,B('On the demo calendar','En el calendario de prueba'),'calendar'],[B('Unread messages','Mensajes sin leer'),unread.length,B('Awaiting your response','Esperan respuesta'),'message']].map(x=>`<div class="metric card"><div><small>${x[0]}</small><strong>${x[1]}</strong><div class="foot">${x[2]}</div></div><span class="metric-icon">${i(x[3])}</span></div>`).join('')}</div><div class="grid-2"><section class="card card-pad">${cardTitle(B('Needs your attention','Requiere tu atención'),B('Start with the work that matters most.','Comienza por lo más importante.'),`<button class="link-btn" data-action="navigate" data-id="plans">${B('Review menus','Revisar menús')} ${i('arrow')}</button>`)}${alerts.map(a=>`<div class="task"><span class="task-icon ${a.page==='groceries'?'warn':''}">${i(a.icon)}</span><div><strong>${a.title}</strong><small>${a.sub}</small></div><button class="link-btn" data-action="navigate" data-id="${a.page}">${B('Open','Abrir')} ${i('arrow')}</button></div>`).join('')}</section><section class="card card-pad">${cardTitle(B('Coming up','Próximamente'),B('Appointments on the demonstration schedule.','Citas en el calendario de ejemplo.'),`<button class="link-btn" data-action="navigate" data-id="appointments">${B('Calendar','Calendario')} ${i('arrow')}</button>`)}${upcoming.slice(0,3).map(a=>`<div class="mini-row"><div><strong>${person(a.client)}</strong><small>${a.type==='intro'?B('Complimentary introduction','Presentación gratuita'):B('Guided nutrition consultation','Consulta nutricional guiada')} · ${a.duration} ${B('min','min')}</small></div><div class="date">${formatDate(a.date,{month:'short',day:'numeric'})} · ${a.time}</div></div>`).join('')}</section></div><div class="quicklinks"><button class="quicklink" data-action="navigate" data-id="clients">${i('users')}<strong>${B('Customer directory','Directorio de clientes')}</strong><small>${B('Profiles, preferences and service access','Perfiles, preferencias y servicios')}</small></button><button class="quicklink" data-action="navigate" data-id="plans">${i('shield')}<strong>${B('Professional menu review','Revisión profesional de menús')}</strong><small>${B('Review AI suggestions before release','Aprueba propuestas de IA antes de enviarlas')}</small></button><button class="quicklink" data-action="navigate" data-id="credits">${i('wallet')}<strong>${B('Consultation credit ledger','Registro de créditos')}</strong><small>${B('Grants, reservations and usage','Asignaciones, reservas y uso')}</small></button></div>`}
function clientsPage(){if(live)return liveClientsPage();const items=data.clients.filter(c=>(ui.filter==='all'||c.status===ui.filter)&&(c.name+' '+c.email+' '+c.plan).toLowerCase().includes(ui.search.toLowerCase()));return `${head(B('PEOPLE & RELATIONSHIPS','PERSONAS Y RELACIONES'),B('Your clients','Tus clientes'),B('Know who you are caring for, what they need, and where they are in their program.','Conoce a tus clientes, sus necesidades y cómo avanzan en su programa.'),uiButton('new-client',B('Add demo client','Agregar cliente ficticio'),'','','plus'))}<section class="card card-pad"><div class="filterbar"><label class="search">${i('search')}<input id="client-search" type="search" autocomplete="off" placeholder="${B('Search name or program','Buscar nombre o programa')}" value="${escapeHTML(ui.search)}" aria-label="${B('Search clients','Buscar clientes')}"></label><select class="select" id="client-filter" aria-label="${B('Filter clients','Filtrar clientes')}"><option value="all" ${ui.filter==='all'?'selected':''}>${B('All clients','Todos')}</option><option value="active" ${ui.filter==='active'?'selected':''}>${B('Active','Activos')}</option><option value="ending" ${ui.filter==='ending'?'selected':''}>${B('Ending soon','Por finalizar')}</option><option value="paused" ${ui.filter==='paused'?'selected':''}>${B('Paused','Pausados')}</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>${B('Customer','Cliente')}</th><th>${B('Service','Servicio')}</th><th>${B('Menu','Menú')}</th><th>${B('Credits available','Créditos disponibles')}</th><th>${B('Status','Estado')}</th><th></th></tr></thead><tbody>${items.map(c=>`<tr><td><div class="client-cell"><span class="initials ${c.id==='c4'?'warm':''}">${initials(c.name)}</span><span><strong>${escapeHTML(c.name)}</strong><small>${escapeHTML(c.email)}</small></span></div></td><td>${c.tier==='guided'?B('Guided care','Atención guiada'):B('28-day digital','Digital de 28 días')}</td><td>${statusPill(c.menu)}</td><td>${c.tier==='guided'?available(c):'—'}</td><td>${statusPill(c.status)}</td><td><button class="link-btn" data-action="client" data-id="${c.id}">${B('Open profile','Ver perfil')} ${i('chevron')}</button></td></tr>`).join('')||`<tr><td colspan="6" class="empty">${B('No customers match this filter.','No hay clientes con este filtro.')}</td></tr>`}</tbody></table></div></section>`}
const dayNames=()=>lang==='es'?['Lun','Mar','Mié','Jue','Vie','Sáb','Dom']:['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];
function plansPage(){let arr=data.plans.filter(p=>ui.planFilter==='all'||p.status===ui.planFilter);return `${head(B('CLINICAL OVERSIGHT','SUPERVISIÓN PROFESIONAL'),B('Menu review queue','Revisión de menús'),B('AI-generated suggestions stay in draft until the appropriate professional review is complete.','Las propuestas de IA permanecen en borrador hasta que se complete la revisión profesional.'),uiButton('new-plan',B('Create menu draft','Crear borrador de menú'),'','','plus'))}<div class="notice warn mb">${i('shield')}<div>${B('Demo-only decisions. Allergy flags and missing assessments block approval; no menu is sent to real customers.','Decisiones solo de demostración. Las alertas de alergias o evaluaciones faltantes impiden la aprobación; no se envía ningún menú real.')}</div></div><div class="filterbar"><select class="select" id="plan-filter" aria-label="${B('Plan status','Estado del plan')}"><option value="review" ${ui.planFilter==='review'?'selected':''}>${B('Needs approval','Pendientes')}</option><option value="all" ${ui.planFilter==='all'?'selected':''}>${B('All plans','Todos los planes')}</option><option value="approved" ${ui.planFilter==='approved'?'selected':''}>${B('Approved','Aprobados')}</option><option value="revision" ${ui.planFilter==='revision'?'selected':''}>${B('Needs revision','Requieren cambios')}</option></select></div><div class="data-list">${arr.map(p=>`<article class="queue"><div><div class="q-meta">${p.source==='ai'?B('AI-ASSISTED PROPOSAL','PROPUESTA ASISTIDA POR IA'):B('REVIEWED PLAN','PLAN REVISADO')} · ${formatDate(p.updated,{month:'short',day:'numeric'})}</div><strong>${person(p.client)} · ${B('7-day draft menu','Menú de 7 días')}</strong><p>${escapeHTML(p.note)}</p>${p.blocked?`<p style="color:#a36d42;margin-top:8px">${i('alert')} ${B('Approval blocked: intake/safety check unresolved','Aprobación bloqueada: falta revisión de seguridad')}</p>`:''}</div><div class="queue-right">${statusPill(p.status)}${uiButton('review-plan',B('Review menu','Revisar menú'),'ghost',`data-id="${p.id}"`,'arrow')}</div></article>`).join('')||`<div class="card empty">${B('No menus in this view.','No hay menús en esta vista.')}</div>`}</div>`}
function recipesPage(){let arr=recipes.filter(r=>ui.recipeFilter==='all'||(ui.recipeFilter==='approved'?r.approved:!r.approved));return `${head(B('YOUR RECIPE FOUNDATION','TU BASE DE RECETAS'),B('Recipe library','Recetario'),B('Meals and substitutions should be reviewed before the AI planner can use them.','Las recetas y sustituciones deben revisarse antes de que las utilice la IA.'),uiButton('recipe-info',B('Recipe requirements','Requisitos de recetas'),'ghost','','file'))}<div class="notice mb">${i('leaf')}<div>${B('This is a sample library. Real recipes need checked amounts, nutrition data, allergens, bilingual instructions, serving rules and version history.','Este es un recetario de ejemplo. Las recetas reales necesitan cantidades, nutrición, alérgenos, instrucciones bilingües y control de versiones.')}</div></div><section class="card card-pad"><div class="filterbar"><select class="select" id="recipe-filter"><option value="all" ${ui.recipeFilter==='all'?'selected':''}>${B('All recipes','Todas las recetas')}</option><option value="approved" ${ui.recipeFilter==='approved'?'selected':''}>${B('Approved','Aprobadas')}</option><option value="draft" ${ui.recipeFilter==='draft'?'selected':''}>${B('Drafts','Borradores')}</option></select></div><div class="table-wrap"><table class="table"><thead><tr><th>${B('Recipe','Receta')}</th><th>${B('Cook time','Tiempo')}</th><th>${B('Difficulty','Dificultad')}</th><th>${B('Review','Revisión')}</th><th></th></tr></thead><tbody>${arr.map(r=>`<tr><td><strong>${escapeHTML(lang==='es'?r.es:r.en)}</strong><small>${escapeHTML(r.ing.slice(0,3).map(ingredientName).join(' · '))}</small></td><td>${r.time} min</td><td>${r.complex==='easy'?B('Easy','Fácil'):B('Moderate','Intermedia')}</td><td>${r.approved?statusPill('approved'):statusPill('review')}</td><td><button class="link-btn" data-action="recipe" data-id="${r.id}">${B('View recipe','Ver receta')} ${i('chevron')}</button></td></tr>`).join('')}</tbody></table></div></section>`}
function apptsPage(){let appts=[...data.appointments].sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).filter(a=>ui.apptFilter==='all'||(ui.apptFilter==='upcoming'?a.status==='scheduled':a.status===ui.apptFilter));return `${head(B('TIME FOR CONVERSATION','TIEMPO PARA CONVERSAR'),B('Consultations','Consultas'),B('Schedule sessions, protect your time, and keep credit reservations transparent.','Organiza las consultas, cuida tu tiempo y lleva un control claro de los créditos.'),uiButton('new-appt',B('Schedule demo session','Programar cita de prueba'),'','','plus'))}<div class="notice mb">${i('clock')}<div>${B('No live calendar integration or real availability checks. Scheduled appointments reserve credits in this demo; credits are spent only when a session is marked completed.','No hay conexión con un calendario real. Las citas reservan créditos en esta demostración; solo se descuentan al marcar la consulta como completada.')}</div></div><div class="filterbar"><select class="select" id="appt-filter"><option value="upcoming" ${ui.apptFilter==='upcoming'?'selected':''}>${B('Upcoming','Próximas')}</option><option value="all" ${ui.apptFilter==='all'?'selected':''}>${B('All appointments','Todas')}</option><option value="completed" ${ui.apptFilter==='completed'?'selected':''}>${B('Completed','Completadas')}</option><option value="cancelled" ${ui.apptFilter==='cancelled'?'selected':''}>${B('Cancelled','Canceladas')}</option></select></div><div class="calendar-pair"><section class="card card-pad">${cardTitle(B('Appointment schedule','Agenda de consultas'),B('30 minutes per paid credit in this illustrative setup.','30 minutos por crédito de pago en este ejemplo.'))}${appts.map(a=>`<div class="appt"><div class="appt-date"><span>${formatDate(a.date,{month:'short'})}</span><b>${new Date(`${a.date}T12:00:00`).getDate()}</b></div><div class="appt-info"><strong>${person(a.client)}</strong><p>${a.type==='intro'?B('Free 15-minute introduction','Presentación gratuita de 15 minutos'):B('Personal nutrition consultation','Consulta nutricional personalizada')} · ${a.duration} min · ${a.type==='paid'?`${Math.ceil(a.duration/30)} ${B('credit(s)','crédito(s)')}`:B('No credits','Sin créditos')}</p><div class="flex">${statusPill(a.status)}${a.status==='scheduled'?`${uiButton('complete-appt',B('Complete','Completar'),'ghost tiny',`data-id="${a.id}"`)}${uiButton('cancel-appt',B('Cancel','Cancelar'),'danger tiny',`data-id="${a.id}"`)}`:''}</div></div><div class="appt-time">${a.time}</div></div>`).join('')||`<div class="empty">${B('No appointments here.','No hay citas aquí.')}</div>`}</section><section class="card card-pad">${cardTitle(B('Consultation approach','Nuestra forma de atender'),B('Warm, practical, relationship-first service.','Atención cercana, práctica y humana.'))}<div class="stack"><div class="notice">${i('heart')}<div>${B('Encourage one 30-minute credit at a time so clients can apply advice between sessions. Longer sessions can use multiple credits.','Recomienda un crédito de 30 minutos por sesión para que puedan aplicar los consejos entre citas. Las sesiones largas usan varios créditos.')}</div></div><div class="notice">${i('calendar')}<div>${B('Free 15-minute introductions are separate from paid credits. A proposed 1–2 month grace window remains a policy decision.','Las presentaciones gratuitas de 15 minutos son independientes de los créditos pagados. El período de gracia de 1 a 2 meses sigue pendiente de definir.')}</div></div><div class="notice warn">${i('alert')}<div>${B('A production calendar must prevent overlaps, verify availability, apply cancellation policies, and use local time zones.','El calendario real debe evitar choques, verificar disponibilidad, aplicar cancelaciones y manejar zonas horarias.')}</div></div></div></section></div>`}
function creditsPage(){let c=client(ui.creditClient)||data.clients[0];let entries=data.ledger.filter(x=>x.client===c.id);return `${head(B('FLEXIBLE PROFESSIONAL SUPPORT','APOYO PROFESIONAL FLEXIBLE'),B('Consultation credits','Créditos de consulta'),B('Give customers freedom to use their time when they need it, without losing track of reserved sessions.','Ofrece flexibilidad para usar las consultas cuando más las necesiten, con reservas claras.'),uiButton('add-credits',B('Adjust demo credits','Ajustar créditos de prueba'),'','','plus'))}<div class="grid-half"><section class="card card-pad">${cardTitle(B('Client balance','Saldo por cliente'),B('Choose a client to inspect available and reserved time.','Elige un cliente para revisar créditos disponibles y reservados.'))}<div class="form-field"><label>${B('Client','Cliente')}</label><select id="credit-client" class="select">${data.clients.filter(c=>c.tier==='guided').map(x=>`<option value="${x.id}" ${x.id===c.id?'selected':''}>${escapeHTML(x.name)}</option>`).join('')}</select></div><div class="balance"><div><small>${B('Available credits','Créditos disponibles')}</small><strong>${available(c)}</strong></div><div style="text-align:right"><small>${B('Reserved for appointments','Reservados para citas')}</small><strong>${holds(c.id)}</strong></div></div><div class="kv"><label>${B('Unused paid credits (before reservations)','Créditos pagados sin usar (antes de reservas)')}</label><b>${c.credits}</b></div><div class="kv"><label>${B('Illustrative time per credit','Tiempo de ejemplo por crédito')}</label><b>30 min</b></div><div class="kv"><label>${B('Complimentary introduction','Presentación gratuita')}</label><b>${c.introUsed?B('Already used','Ya utilizada'):B('Potentially available','Posiblemente disponible')}</b></div></section><section class="card card-pad">${cardTitle(B('Credit activity','Movimiento de créditos'),B('Example ledger events for selected client.','Movimientos de ejemplo del cliente seleccionado.'))}${entries.length?entries.map(x=>`<div class="ledger-entry"><div><strong>${escapeHTML(x.desc)}</strong><small>${formatDate(x.date,{month:'short',day:'numeric',year:'numeric'})}</small></div><div class="amount ${x.amount<0?'minus':''}">${x.amount>0?'+':''}${x.amount}</div></div>`).join(''):`<div class="empty">${B('No ledger events yet.','Aún no hay movimientos.')}</div>`}</section></div><div class="card card-pad mt">${cardTitle(B('Policies still to confirm','Políticas por confirmar'),B('Customer care should not depend on arbitrary credit forfeiture.','La atención al cliente no debe depender de la pérdida arbitraria de créditos.'))}<div class="grid-half"><div class="notice">${i('heart')}<div>${B('Grace period: consider 1–2 months after program end. Paid-credit expiration rules require a deliberate policy and legal review.','Período de gracia: considerar 1 a 2 meses después del programa. El vencimiento de créditos pagados requiere una política y revisión legal.')}</div></div><div class="notice">${i('clock')}<div>${B('Single appointments are the default. Multiple credits can fund longer sessions, while booking and cancellation rules remain configurable.','Una consulta a la vez es lo habitual. Varios créditos pueden cubrir sesiones largas; las reglas de reservas siguen configurables.')}</div></div></div></div>`}
function servicesPage(){return `${head(B('CARE OFFERINGS','SERVICIOS DE NUTRICIÓN'),B('Programs & packages','Programas y paquetes'),B('Review what customers receive and how credits support each level of care. Prices and final policies are intentionally undecided.','Revisa qué incluye cada servicio y cómo funcionan los créditos. Los precios y políticas finales siguen pendientes.'),uiButton('service-info',B('Package policy notes','Notas de paquetes'),'ghost','','file'))}<div class="notice warn mb">${i('alert')}<div>${B('Illustrative catalog only: names and credit counts are examples, not published prices or commitments. Changes here stay in this demonstration.','Catálogo ilustrativo: nombres y créditos son ejemplos, no precios ni compromisos publicados. Los cambios permanecen en esta demo.')}</div></div><div class="grid-half">${data.packages.map(s=>`<section class="card card-pad">${cardTitle(escapeHTML(lang==='es'?s.es:s.en),s.level==='digital'?B('Self-guided meal planning','Planificación autoguiada'):B('Professional support with flexible scheduling','Acompañamiento profesional con horario flexible'))}<div class="kv"><label>${B('Program length','Duración')}</label><b>${s.months?`${s.months} ${B('months','meses')}`:B('28 days','28 días')}</b></div><div class="kv"><label>${B('Included consultation credits','Créditos incluidos')}</label><b>${s.credits}</b></div><div class="kv"><label>${B('Optional free introduction','Presentación gratuita opcional')}</label><b>15 min</b></div><div class="kv"><label>${B('Published price','Precio publicado')}</label><b>${B('Not decided','No definido')}</b></div><div class="mt">${uiButton('edit-service',B('Edit example credits','Editar créditos de ejemplo'),'ghost tiny',`data-id="${s.id}"`,'edit')}</div></section>`).join('')}</div><div class="card card-pad mt">${cardTitle(B('Service design principles','Principios del servicio'),B('A meaningful difference between self-guided products and professional support.','Una diferencia clara entre productos autoguiados y atención profesional.'))}<div class="grid-half"><div class="notice">${i('book')}<div>${B('Digital customers independently follow their menu, but still receive convenient grocery tools and an optional free introduction.','Los clientes digitales siguen su menú por su cuenta, pero reciben herramientas de compras y una presentación gratuita opcional.')}</div></div><div class="notice">${i('heart')}<div>${B('Guided clients use credits on their own schedule, with dietitian-reviewed changes and supportive check-ins.','Los clientes guiados usan sus créditos según sus necesidades, con ajustes revisados por la dietista y seguimiento cercano.')}</div></div></div></div>`}
function messagesPage(){if(!data.messages.some(m=>m.id===ui.messageId))ui.messageId=data.messages[0]?.id;let m=data.messages.find(x=>x.id===ui.messageId);return `${head(B('SUPPORT & CONTINUITY','APOYO Y CONTINUIDAD'),B('Client messages','Mensajes de clientes'),B('Answer quick questions thoughtfully, and guide more complex concerns toward a proper consultation.','Responde dudas puntuales con cercanía y orienta los asuntos complejos hacia una consulta.'),uiButton('message-guide',B('Message boundaries','Límites de mensajería'),'ghost','','shield'))}<div class="split-threads"><div class="card thread-list">${data.messages.map(x=>`<button class="thread-btn ${x.id===ui.messageId?'active':''}" data-action="thread" data-id="${x.id}"><div class="row-between"><strong>${person(x.client)}</strong>${x.unread&&!x.closed?'<span class="pill warn">'+B('New','Nuevo')+'</span>':''}</div><small>${escapeHTML(lang==='es'?x.topicEs:x.topic)}</small><span>${escapeHTML((x.items.at(-1)?.[lang==='es'&&x.items.at(-1).textEs?'textEs':'text'])||'')}</span></button>`).join('')}</div><section class="card chat">${m?`<div class="chat-top"><div><strong>${person(m.client)}</strong><div class="muted small">${escapeHTML(lang==='es'?m.topicEs:m.topic)}</div></div><button class="btn ghost tiny" data-action="toggle-thread" data-id="${m.id}">${m.closed?B('Reopen','Reabrir'):B('Mark resolved','Marcar resuelto')}</button></div><div class="messages">${m.items.map(b=>`<div class="bubble ${b.who==='staff'?'out':''}">${escapeHTML(lang==='es'&&b.textEs?b.textEs:b.text)}<small>${b.who==='staff'?B('Dietitian team','Equipo de nutrición'):person(m.client)} · ${escapeHTML(b.time)}</small></div>`).join('')}</div>${m.closed?`<div class="notice">${i('checkCircle')} ${B('Conversation resolved. Reopen to reply.','Conversación resuelta. Reabre para responder.')}</div>`:`<form id="message-form" class="chat-compose"><textarea name="message" placeholder="${B('Write a thoughtful, brief response…','Escribe una respuesta breve y amable…')}" required></textarea><button class="btn" type="submit">${i('send')} ${B('Reply','Responder')}</button></form>`}`:`<div class="empty">${B('Select a conversation.','Elige una conversación.')}</div>`}</section></div>`}
function groceryPage(){const arr=data.groceries.filter(g=>ui.groceryFilter==='all'||g.status===ui.groceryFilter);return `${head(B('LOW-FRICTION GROCERY PLANNING','COMPRAS SIN COMPLICACIONES'),B('Grocery reviews','Revisión de compras'),B('Catch ingredient and shopping-list problems before customers review their retailer cart.','Resuelve problemas de ingredientes antes de que el cliente revise su carrito.'),uiButton('grocery-info',B('Integration notes','Notas de integración'),'ghost','','file'))}<div class="notice mb">${i('basket')}<div>${B('No retailer API is connected. Availability and substitution examples are fictional; grocery orders must always be confirmed by the customer at the retailer.','No hay una conexión con tiendas. La disponibilidad y sustituciones son ficticias; el cliente siempre debe confirmar la compra con la tienda.')}</div></div><div class="filterbar"><select class="select" id="grocery-filter"><option value="open" ${ui.groceryFilter==='open'?'selected':''}>${B('Needs attention','Pendientes')}</option><option value="all" ${ui.groceryFilter==='all'?'selected':''}>${B('All issues','Todos')}</option><option value="resolved" ${ui.groceryFilter==='resolved'?'selected':''}>${B('Resolved','Resueltos')}</option></select></div><section class="card card-pad">${arr.map(g=>`<div class="grocery-row"><div class="alert-icon">${i(g.status==='resolved'?'checkCircle':'alert')}</div><div><strong>${person(g.client)} · ${escapeHTML(lang==='es'?g.itemEs:g.item)}</strong><p>${escapeHTML(lang==='es'?g.issueEs:g.issue)}</p><p style="color:#607a5e">${escapeHTML(lang==='es'?g.subEs:g.sub)}</p></div>${g.status==='open'?uiButton('resolve-grocery',B('Mark reviewed','Marcar revisado'),'ghost tiny',`data-id="${g.id}"`):statusPill('resolved')}</div>`).join('')||`<div class="empty">${B('All grocery issues in this view have been reviewed.','Todos los detalles de compras en esta vista están revisados.')}</div>`}</section>`}
function settingsPage(){return `${head(B('PRACTICE SETTINGS','CONFIGURACIÓN'),B('Practice preferences','Preferencias del consultorio'),B('Placeholders for the operational rules your developer will connect later.','Espacios para las reglas operativas que el desarrollador conectará después.'))}<div class="grid-half"><section class="card card-pad">${cardTitle(B('Care philosophy','Filosofía de atención'),B('Keep the human relationship at the center.','Las relaciones humanas son lo más importante.'))}<div class="list-item"><strong>${B('Optional introduction','Presentación opcional')}</strong><p>${B('Every customer can meet the dietitian; 28-day digital clients are offered a complimentary 15-minute call.','Todos pueden conocer a su dietista; el cliente del menú digital recibe una llamada gratuita opcional de 15 minutos.')}</p></div><div class="list-item"><strong>${B('Flexible credits','Créditos flexibles')}</strong><p>${B('The current working model is one 30-minute block per credit; longer sessions use additional credits.','El modelo actual contempla 30 minutos por crédito; las sesiones largas usan créditos adicionales.')}</p></div><div class="list-item"><strong>${B('Warm follow-up','Seguimiento cercano')}</strong><p>${B('Avoid abrupt credit loss after program completion; the proposed grace window is 1–2 months.','Evitar la pérdida inmediata de créditos al terminar el programa; se contempla un período de gracia de 1 a 2 meses.')}</p></div></section><section class="card card-pad">${cardTitle(B('Production readiness','Preparación para producción'),B('Required before handling real customer information.','Obligatorio antes de manejar datos reales.'))}<div class="stack">${[[B('Secure staff authentication and role-based access','Acceso seguro para el personal y permisos por rol'),'lock'],[B('Privacy, consent, access logs and data retention','Privacidad, consentimiento y registro de acceso'),'shield'],[B('Live customer database, plans and approved versions','Base de clientes, planes y versiones aprobadas'),'users'],[B('Calendar, billing and auditable credit ledger','Agenda, cobros y registro auditable de créditos'),'wallet'],[B('Authorized grocery retailer integrations','Integraciones autorizadas con tiendas'),'basket']].map(x=>`<div class="flex">${i(x[1])}<span class="small">${x[0]}</span></div>`).join('')}</div></section></div><section class="card card-pad mt">${cardTitle(B('Demo controls','Controles de demostración'),B('Changes stay in this browser tab, except language preference.','Los cambios quedan en esta pestaña, excepto el idioma.'))}<div class="flex">${uiButton('reset',B('Restore fictional demo data','Restablecer datos ficticios'),'ghost','','history')}<span class="muted small">${B('No real customers or appointments are connected.','No hay clientes ni citas reales conectados.')}</span></div></section>`}
function renderPage(){return ({overview,clients:clientsPage,plans:plansPage,recipes:recipesPage,appointments:apptsPage,credits:creditsPage,services:servicesPage,messages:messagesPage,groceries:groceryPage,settings:settingsPage})[ui.page]?.()||overview()}
function modalHeader(title,sub=''){return `<div class="drawer-head"><div><div class="eyebrow">${B('PRACTICE DEMO','DEMO DE CONSULTORIO')}</div><h2>${title}</h2>${sub?`<p>${sub}</p>`:''}</div><button class="icon-btn" aria-label="${B('Close','Cerrar')}" data-action="close-modal">${i('close')}</button></div>`}
function clientDrawer(c){let tab=ui.detailTab;let p=data.plans.find(p=>p.client===c.id);let apps=data.appointments.filter(a=>a.client===c.id);let led=data.ledger.filter(x=>x.client===c.id);return `<div class="backdrop" data-action="close-modal"><section role="dialog" aria-modal="true" aria-label="${B('Client profile','Perfil del cliente')}" class="drawer" data-stop><div class="drawer-head"><div class="flex" style="gap:12px"><span class="initials" style="width:50px;height:50px;font-size:19px">${initials(c.name)}</span><div><h2>${escapeHTML(c.name)}</h2><p>${escapeHTML(c.email)} · ${c.tier==='guided'?B('Guided support','Atención guiada'):B('Self-guided program','Programa autoguiado')}</p></div></div><button class="icon-btn" data-action="close-modal" aria-label="Close">${i('close')}</button></div><div class="flex">${statusPill(c.status)}${statusPill(c.menu)}<span class="pill neutral">${c.lang.toUpperCase()}</span></div><div class="detail-actions">${uiButton('client-plan',B('Manage menu','Administrar menú'),'ghost tiny',`data-id="${c.id}"`,'chef')}${uiButton('client-book',B('Book time','Agendar consulta'),'ghost tiny',`data-id="${c.id}"`,'calendar')}${uiButton('client-message',B('Message','Mensaje'),'ghost tiny',`data-id="${c.id}"`,'message')}</div><div class="tabs">${[['profile',B('Profile','Perfil')],['plan',B('Menu','Menú')],['credits',B('Credits','Créditos')],['history',B('History','Historial')]].map(([k,v])=>`<button class="tab ${tab===k?'active':''}" data-action="detail-tab" data-id="${k}">${v}</button>`).join('')}</div>${tab==='profile'?`<dl class="inline-details"><dt>${B('Program','Programa')}</dt><dd>${escapeHTML(c.plan)}</dd><dt>${B('Household','Hogar')}</dt><dd>${c.household} ${B('people','personas')}</dd><dt>${B('Cooking comfort','Nivel de cocina')}</dt><dd>${escapeHTML(c.skill)}</dd><dt>${B('Cooking time','Tiempo disponible')}</dt><dd>${c.time} min</dd><dt>${B('Weekly budget','Presupuesto semanal')}</dt><dd>$${c.budget}</dd><dt>${B('Store preference','Tienda preferida')}</dt><dd>${escapeHTML(c.store)}</dd><dt>${B('Preferred language','Idioma preferido')}</dt><dd>${c.lang==='es'?'Español':'English'}</dd></dl><div class="notice mt">${i('shield')}<div>${B('Fictional profile. In production, keep clinical notes separately permissioned and audit access.','Perfil ficticio. En producción, protege las notas clínicas con permisos y auditoría.')}</div></div>`:tab==='plan'?`<div class="row-between"><div><strong>${B('Current menu','Menú actual')}</strong><p class="muted small">${p?B('7-day menu draft / review','Borrador de menú de 7 días'):B('No draft yet','Aún no hay borrador')}</p></div>${p?statusPill(p.status):''}</div>${p?`<div class="list-item">${p.meals.map((r,j)=>`<div class="kv"><label>${dayNames()[j]}</label><b>${escapeHTML(lang==='es'?recipe(r).es:recipe(r).en)}</b></div>`).join('')}</div>`:`<div class="empty">${B('A new plan can be drafted from the approved recipe library.','Puede crearse un nuevo menú con recetas aprobadas.')}</div>`}${uiButton('client-plan',B('Open menu workflow','Abrir flujo de menús'),'ghost',`data-id="${c.id}"`,'arrow')}`:tab==='credits'?`<div class="balance"><div><small>${B('Available','Disponibles')}</small><strong>${available(c)}</strong></div><div style="text-align:right"><small>${B('Reserved','Reservados')}</small><strong>${holds(c.id)}</strong></div></div>${c.tier==='guided'?`<div class="mt">${uiButton('client-credits',B('Open credit ledger','Abrir registro de créditos'),'ghost',`data-id="${c.id}"`,'arrow')}</div>`:`<p class="muted small">${B('No paid consultation package is assigned.','No tiene asignado un paquete de consultas pagadas.')}</p>`}`:`${cardTitle(B('Recent activity','Actividad reciente'),'', '')}${apps.map(a=>`<div class="list-item"><strong>${formatDate(a.date,{month:'short',day:'numeric'})} · ${a.duration} min</strong><p>${a.type==='intro'?B('Complimentary introduction','Presentación gratuita'):B('Consultation','Consulta')} · ${statusLabel(a.status)}</p></div>`).join('')||`<p class="muted small">${B('No sessions in the demonstration calendar.','No hay sesiones en el calendario de ejemplo.')}</p>`}${led.map(l=>`<div class="list-item"><strong>${escapeHTML(l.desc)}</strong><p>${l.amount>0?'+':''}${l.amount} ${B('credit(s)','crédito(s)')}</p></div>`).join('')}`}</section></div>`}
function reviewModal(p){let c=client(p.client);return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Review menu','Revisar menú')}" data-stop>${modalHeader(B('Review proposed menu','Revisar menú propuesto'),`${escapeHTML(c?.name)} · ${B('Illustrative 7-day menu','Menú de 7 días de ejemplo')}`)}<div class="notice ${p.blocked?'danger':''}">${i(p.blocked?'alert':'shield')}<div>${p.blocked?B('Approval blocked: allergy or intake verification is incomplete. Return for revision rather than release.','Aprobación bloqueada: falta verificar alergias o evaluación. Devuélvelo para revisión.'):B('Professional review required. Changes below affect only this fictional draft; no client receives a plan.','Se requiere revisión profesional. Los cambios solo afectan este borrador ficticio; nadie recibe un plan.')}</div></div><p class="muted small">${escapeHTML(p.note)}</p><div class="review-days">${p.meals.map((r,j)=>`<div class="review-day"><b>${dayNames()[j]}</b><select data-meal-change="${j}" aria-label="${B('Recipe for','Receta para')} ${dayNames()[j]}">${recipes.filter(r=>r.approved).map(x=>`<option value="${x.id}" ${r===x.id?'selected':''}>${escapeHTML(lang==='es'?x.es:x.en)}</option>`).join('')}</select></div>`).join('')}</div><div class="form-field"><label for="review-note">${B('Notes for revision / approval history','Notas para revisión o aprobación')}</label><textarea id="review-note" placeholder="${B('Write a brief professional note (demo only).','Escribe una nota profesional breve (solo demostración).')}"></textarea></div><div class="modal-actions">${uiButton('request-revision',B('Return for revision','Devolver para revisión'),'ghost',`data-id="${p.id}"`)}${uiButton('approve-plan',B('Approve draft (demo)','Aprobar borrador (demo)'),'',`data-id="${p.id}" ${p.blocked?'disabled':''}`,'checkCircle')}</div></section></div>`}
function newClientModal(){return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Add demo client','Agregar cliente de prueba')}" data-stop>${modalHeader(B('Add a fictional client','Agregar cliente ficticio'),B('Demo state only. Do not enter actual customer details.','Solo de prueba. No ingreses datos de clientes reales.'))}<form id="new-client-form"><div class="form-grid"><div class="form-field"><label>${B('Demo name','Nombre ficticio')}</label><input name="name" required minlength="2" maxlength="60" value="Sample Customer"></div><div class="form-field"><label>${B('Program type','Tipo de programa')}</label><select name="tier"><option value="digital">${B('28-day digital','Digital de 28 días')}</option><option value="guided">${B('Guided support','Atención guiada')}</option></select></div><div class="form-field"><label>${B('Preferred language','Idioma preferido')}</label><select name="lang"><option value="en">English</option><option value="es">Español</option></select></div><div class="form-field"><label>${B('Household size','Personas en casa')}</label><input name="household" type="number" min="1" max="12" value="2"></div></div><div class="notice">${i('alert')}<div>${B('Do not collect actual emails, medical histories or identifiable information in this demo.','No recopiles correos, historiales clínicos ni datos identificables reales en esta demo.')}</div></div><div class="modal-actions"><button class="btn ghost" type="button" data-action="close-modal">${B('Cancel','Cancelar')}</button><button class="btn" type="submit">${B('Add sample client','Agregar cliente de prueba')}</button></div></form></section></div>`}
function newPlanModal(){return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Create menu draft','Crear borrador')}" data-stop>${modalHeader(B('Start a menu draft','Crear borrador de menú'),B('Begin with dietitian-approved recipe selections.','Empieza con recetas aprobadas por la dietista.'))}<form id="new-plan-form"><div class="form-field"><label>${B('Client','Cliente')}</label><select name="client">${data.clients.map(c=>`<option value="${c.id}">${escapeHTML(c.name)}</option>`).join('')}</select></div><div class="form-field"><label>${B('Planning note','Nota de planificación')}</label><textarea name="note" maxlength="250" placeholder="${B('Household preferences, cooking limits, ingredient budget…','Preferencias familiares, tiempo de cocina, presupuesto…')}"></textarea></div><div class="notice warn">${i('shield')}<div>${B('The system assembles a placeholder week from approved recipes. The dietitian must review it before any production release.','El sistema arma una semana de ejemplo con recetas aprobadas. La dietista debe revisarla antes de publicarla.')}</div></div><div class="modal-actions"><button class="btn ghost" type="button" data-action="close-modal">${B('Cancel','Cancelar')}</button><button class="btn" type="submit">${B('Create draft','Crear borrador')}</button></div></form></section></div>`}
function newApptModal(defaultClient=''){let cust=client(defaultClient)||data.clients[0];return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Schedule session','Programar consulta')}" data-stop>${modalHeader(B('Schedule a demo session','Programar consulta de prueba'),B('No real calendar availability or customer notification.','No hay disponibilidad real ni notificaciones al cliente.'))}<form id="new-appt-form"><div class="form-grid"><div class="form-field"><label>${B('Customer','Cliente')}</label><select name="client">${data.clients.map(c=>`<option value="${c.id}" ${cust.id===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></div><div class="form-field"><label>${B('Session type','Tipo de consulta')}</label><select name="type" id="appt-type"><option value="paid">${B('Paid consultation','Consulta pagada')}</option><option value="intro">${B('Free introduction','Presentación gratuita')}</option></select></div><div class="form-field"><label>${B('Date','Fecha')}</label><input type="date" name="date" min="2026-11-22" value="2026-11-30" required></div><div class="form-field"><label>${B('Time','Hora')}</label><input type="time" name="time" value="10:00" required></div><div class="form-field"><label>${B('Length','Duración')}</label><select name="duration" id="appt-duration"><option value="30">30 min · 1 ${B('credit','crédito')}</option><option value="60">60 min · 2 ${B('credits','créditos')}</option><option value="90">90 min · 3 ${B('credits','créditos')}</option></select></div></div><div class="notice">${i('wallet')}<div>${B('Paid bookings hold their credits until completed or cancelled. Free introductions use no paid credits and are limited to one per client in this demo.','Las citas pagadas reservan créditos hasta completarse o cancelarse. Las presentaciones gratuitas no utilizan créditos y se limitan a una por cliente en esta demostración.')}</div></div><div class="modal-actions"><button class="btn ghost" type="button" data-action="close-modal">${B('Cancel','Cancelar')}</button><button class="btn" type="submit">${B('Reserve in demo','Reservar en demo')}</button></div></form></section></div>`}
function creditsModal(){return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Adjust demo credits','Ajustar créditos')}" data-stop>${modalHeader(B('Adjust consultation credits','Ajustar créditos de consulta'),B('Creates a fictional ledger adjustment, not a purchase.','Crea un movimiento ficticio, no una compra.'))}<form id="credit-form"><div class="form-field"><label>${B('Client','Cliente')}</label><select name="client">${data.clients.filter(c=>c.tier==='guided').map(c=>`<option value="${c.id}" ${ui.creditClient===c.id?'selected':''}>${escapeHTML(c.name)}</option>`).join('')}</select></div><div class="form-grid"><div class="form-field"><label>${B('Change','Cambio')}</label><input name="amount" type="number" min="-20" max="20" value="1" required></div><div class="form-field"><label>${B('Reason','Motivo')}</label><select name="reason"><option value="Manual demo adjustment">${B('Manual adjustment','Ajuste manual')}</option><option value="Additional consultation credits">${B('Extra consultation credits','Créditos adicionales')}</option><option value="Courtesy extension">${B('Courtesy adjustment','Ajuste de cortesía')}</option></select></div></div><div class="modal-actions"><button type="button" class="btn ghost" data-action="close-modal">${B('Cancel','Cancelar')}</button><button class="btn" type="submit">${B('Save demo change','Guardar ajuste de prueba')}</button></div></form></section></div>`}
function recipeModal(r){return `<div class="backdrop modal-back" data-action="close-modal"><section role="dialog" aria-modal="true" aria-label="${B('Recipe details','Detalle de receta')}" class="modal" data-stop>${modalHeader(escapeHTML(lang==='es'?r.es:r.en),`${r.time} min · ${r.approved?B('Reviewed library item','Receta aprobada'):B('Unapproved draft','Borrador sin aprobar')}`)}<div class="flex">${r.approved?statusPill('approved'):statusPill('review')}<span class="pill neutral">${r.complex==='easy'?B('Easy preparation','Preparación fácil'):B('Moderate preparation','Preparación intermedia')}</span></div><div class="divider"></div><div class="section-head"><h2>${B('Ingredients','Ingredientes')}</h2></div><div class="stack">${r.ing.map(x=>`<div class="kv"><label>${escapeHTML(ingredientName(x))}</label></div>`).join('')}</div><div class="divider"></div><div class="section-head"><h2>${B('Preparation','Preparación')}</h2></div><ol style="color:#657063;font-size:12.5px;line-height:1.9;padding-left:20px">${(lang==='es'?(stepsEs[r.id]||r.steps):r.steps).map(x=>`<li>${escapeHTML(x)}</li>`).join('')}</ol><div class="notice warn mt">${i('alert')}<div>${B('Illustrative ingredients and steps only: no verified quantities, nutrition values or allergen guarantees. Do not use this as a production clinical recipe.','Ingredientes y pasos ilustrativos: no incluyen cantidades ni valores nutricionales verificados. No usar como receta clínica real.')}</div></div></section></div>`}
function serviceModal(s){return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${B('Edit package','Editar paquete')}" data-stop>${modalHeader(B('Edit demo package','Editar paquete de prueba'),escapeHTML(lang==='es'?s.es:s.en))}<form id="service-form"><input type="hidden" name="id" value="${s.id}"><div class="form-field"><label>${B('Included consultation credits','Créditos de consulta incluidos')}</label><input type="number" name="credits" min="0" max="24" value="${s.credits}" required></div><div class="notice">${i('shield')}<div>${B('This changes only the example package definition; it does not modify existing customers or bill anyone.','Solo cambia el paquete de ejemplo; no modifica clientes existentes ni realiza cobros.')}</div></div><div class="modal-actions"><button class="btn ghost" data-action="close-modal" type="button">${B('Cancel','Cancelar')}</button><button class="btn" type="submit">${B('Save demo change','Guardar cambio de prueba')}</button></div></form></section></div>`}
function infoModal(type){let info={
'recipe-info':[B('Production recipe requirements','Requisitos para recetas reales'),B('Each recipe needs versioned bilingual instructions, ingredient quantities, standardized units, portion guidance, allergens, preparation time, a reviewed substitution policy, and verified nutrition values. Only approved versions should be available to the AI planner.','Cada receta necesita instrucciones bilingües versionadas, cantidades, unidades, porciones, alérgenos, tiempo de preparación, sustituciones aprobadas e información nutricional verificada. Solo versiones aprobadas deben estar disponibles para el agente.')],
'message-guide':[B('Messaging boundaries','Límites de mensajería'),B('Free product support is different from brief nutrition questions; a limited allowance for guided clients is under consideration. Significant assessment, personalized changes and extended discussions should move to consultation appointments without automatically charging credits.','La ayuda sobre el producto es distinta de preguntas breves de nutrición; se considera un límite para clientes guiados. Las evaluaciones y cambios personalizados deben trasladarse a consultas, sin descontar créditos automáticamente.')],
'service-info':[B('Service catalog decisions','Decisiones del catálogo'),B('Final package durations, credit quantities, prices, add-on purchases, cancellation rules, and extended paid-credit validity all require owner approval. A 15-minute complimentary introduction remains separate from paid credits.','Las duraciones, cantidades de créditos, precios, compras adicionales, cancelaciones y vigencia de créditos pagados requieren aprobación. La presentación gratuita de 15 minutos no usa créditos pagados.')],
'grocery-info':[B('Retail integrations are not connected','Las tiendas aún no están conectadas'),B('Walmart/Instacart access and terms must be verified. Plan grocery deliveries by week / 3 days / daily and consolidate quantities across household servings. Never place or pay for an order without customer approval.','Hay que verificar acceso y condiciones de Walmart/Instacart. Agrupa compras por semana, tres días o diario, con porciones familiares. Nunca realices pedidos ni cobros sin aprobación del cliente.')]
}[type];return `<div class="backdrop modal-back" data-action="close-modal"><section class="modal" role="dialog" aria-modal="true" aria-label="${info[0]}" data-stop>${modalHeader(info[0])}<p style="color:#5c6b59;line-height:1.8;font-size:13px">${info[1]}</p><div class="modal-actions">${uiButton('close-modal',B('Close','Cerrar'),'ghost')}</div></section></div>`}
function modalMarkup(){if(ui.liveDetail)return liveClientDrawer(ui.liveDetail);if(ui.detail){let c=client(ui.detail);return c?clientDrawer(c):''}if(!ui.modal)return '';if(ui.modal.type==='staff-login')return staffLoginModal();if(ui.modal.type==='staff-client')return staffClientModal();if(ui.modal.type==='review')return reviewModal(data.plans.find(p=>p.id===ui.modal.id));if(ui.modal.type==='client')return newClientModal();if(ui.modal.type==='plan')return newPlanModal();if(ui.modal.type==='appt')return newApptModal(ui.modal.client);if(ui.modal.type==='credits')return creditsModal();if(ui.modal.type==='service')return serviceModal(data.packages.find(s=>s.id===ui.modal.id));if(ui.modal.type==='recipe')return recipeModal(recipe(ui.modal.id));if(ui.modal.type==='info')return infoModal(ui.modal.key);return ''}
function paint({focusSearch=false}={}){let oldY=window.scrollY;document.documentElement.lang=lang;document.getElementById('app').innerHTML=shell();if(focusSearch){const q=document.getElementById('client-search');if(q){q.focus();q.setSelectionRange(q.value.length,q.value.length)}}window.scrollTo(0,oldY)}
function toast(en,es){let e=document.getElementById('toast');if(!e)return;e.textContent=B(en,es);e.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>e.classList.remove('show'),2700)}
function navigate(page){ui.page=page;ui.detail=null;ui.modal=null;ui.menuOpen=false;paint();window.scrollTo(0,0)}
function open(type,id=null){ui.modal={type,id};ui.detail=null;paint()}
function close(){ui.modal=null;ui.detail=null;ui.liveDetail=null;paint()}
function audit(action,note){data.audit.unshift({action,note,when:new Date().toISOString()})}
function dateToday(){return new Date().toISOString().slice(0,10)}
document.addEventListener('click',event=>{let el=event.target.closest('[data-action]');if(!el||event.target.closest('[data-stop]')&&el.dataset.action==='close-modal'&&el===event.target.closest('.backdrop'))return;if(event.target.closest('[data-stop]')===null && event.target.closest('.backdrop') && el.dataset.action!=='close-modal')return;let act=el.dataset.action,id=el.dataset.id;
switch(act){case 'navigate':navigate(id);break;case 'language':lang=id;try{localStorage.setItem('nutri-admin-lang',lang)}catch(e){}paint();break;case 'toggle-menu':ui.menuOpen=!ui.menuOpen;paint();break;case 'close-menu':ui.menuOpen=false;paint();break;case 'close-modal':close();break;case 'staff-login':open('staff-login');break;case 'staff-logout':api('/api/v1/auth/logout',{method:'POST'}).catch(()=>{});live=null;liveClients=[];close();toast(B('Signed out. Demo data shown.','Sesion cerrada. Se muestran datos ficticios.'));break;case 'staff-new-client':if(!(live&&live.roles.indexOf('administrator')>=0)){toast(B('Administrators only in staging.','Solo administradores en staging.'));break}open('staff-client');break;case 'new-client':if(live){toast(B('Signed-in mode: use Add customer.','En sesion: usa Agregar cliente.'));break}open('client');break;case 'new-plan':open('plan');break;case 'new-appt':open('appt');break;case 'add-credits':open('credits');break;case 'client':if(live){openLiveClient(id);break}ui.detail=id;ui.detailTab='profile';ui.modal=null;paint();break;case 'detail-tab':ui.detailTab=id;paint();break;case 'client-plan':{let p=data.plans.find(p=>p.client===id&&p.status==='review');if(p)open('review',p.id);else{ui.page='plans';ui.planFilter='all';close();toast('Choose Create menu draft for this client.','Elige Crear borrador para este cliente.')}break}case 'client-book':ui.modal={type:'appt',client:id};ui.detail=null;paint();break;case 'client-credits':ui.creditClient=id;navigate('credits');break;case 'client-message':{let m=data.messages.find(m=>m.client===id);if(!m){m={id:'m'+Date.now(),client:id,topic:'Client conversation',topicEs:'Conversación con cliente',unread:false,closed:false,items:[]};data.messages.unshift(m)}ui.messageId=m.id;navigate('messages');break}case 'review-plan':open('review',id);break;case 'approve-plan':{let p=data.plans.find(p=>p.id===id);if(!p||p.blocked||p.meals.some(rid=>!recipe(rid).approved)){toast('A safety check still blocks approval.','Una revisión de seguridad impide la aprobación.');break}p.status='approved';p.source='dietitian';p.updated=dateToday();p.note=document.getElementById('review-note')?.value.trim()||p.note;let c=client(p.client);if(c)c.menu='approved';audit('plan-approved',p.id);close();toast('Demo plan approved; no customer was notified.','Plan aprobado en demo; no se notificó al cliente.');break}case 'request-revision':{let p=data.plans.find(p=>p.id===id);if(!p)break;p.status='revision';p.note=document.getElementById('review-note')?.value.trim()||p.note;let c=client(p.client);if(c)c.menu='revision';audit('revision-requested',p.id);close();toast('Draft returned for revision (demo).','Borrador devuelto para revisión (demo).');break}case 'recipe':open('recipe',id);break;case 'edit-service':open('service',id);break;case 'recipe-info':case 'message-guide':case 'grocery-info':case 'service-info':ui.modal={type:'info',key:act};ui.detail=null;paint();break;case 'complete-appt':{let a=data.appointments.find(a=>a.id===id);if(!a||a.status!=='scheduled')break;if(a.type==='paid'){let c=client(a.client);if(!c||c.credits<Math.ceil(a.duration/30)){toast('Credit balance needs review.','Debes revisar el saldo de créditos.');break}let used=Math.ceil(a.duration/30);c.credits-=used;data.ledger.unshift({client:c.id,kind:'use',amount:-used,desc:'Completed consultation',date:dateToday()})}else{let c=client(a.client);if(c)c.introUsed=true}a.status='completed';audit('appt-completed',id);paint();toast('Session marked completed in demo.','Consulta marcada como completada en la demo.');break}case 'cancel-appt':{let a=data.appointments.find(a=>a.id===id);if(!a||a.status!=='scheduled')break;a.status='cancelled';audit('appt-cancelled',id);paint();toast('Appointment cancelled; held credits released.','Cita cancelada; créditos reservados liberados.');break}case 'thread':ui.messageId=id;{let m=data.messages.find(m=>m.id===id);if(m)m.unread=false}paint();break;case 'toggle-thread':{let m=data.messages.find(m=>m.id===id);if(m){m.closed=!m.closed;m.unread=false}paint();break}case 'resolve-grocery':{let g=data.groceries.find(g=>g.id===id);if(g)g.status='resolved';paint();toast('Marked as reviewed in demo.','Marcado como revisado en la demo.');break}case 'reset':data=clone(seed);ui.detail=null;ui.modal=null;ui.page='overview';ui.search='';ui.filter='all';paint();window.scrollTo(0,0);toast('Original fictional demo restored.','Se restauraron los datos ficticios.');break;}});
document.addEventListener('change',e=>{let t=e.target;switch(t.id){case 'client-filter':ui.filter=t.value;paint();break;case 'plan-filter':ui.planFilter=t.value;paint();break;case 'recipe-filter':ui.recipeFilter=t.value;paint();break;case 'appt-filter':ui.apptFilter=t.value;paint();break;case 'credit-client':ui.creditClient=t.value;paint();break;case 'grocery-filter':ui.groceryFilter=t.value;paint();break;case 'appt-type':{let opt=document.getElementById('appt-duration');if(opt){if(t.value==='intro'){opt.innerHTML='<option value="15">15 min · '+B('no credits','sin créditos')+'</option>';opt.disabled=true}else{opt.disabled=false;opt.innerHTML=[30,60,90].map(n=>`<option value="${n}">${n} min · ${n/30} ${B('credits','créditos')}</option>`).join('')}}break}}if(t.dataset.mealChange!==undefined){let p=data.plans.find(x=>x.id===ui.modal?.id);if(p){p.meals[Number(t.dataset.mealChange)]=t.value;toast('Draft meal updated locally.','Comida del borrador actualizada localmente.')}}});
document.addEventListener('input',e=>{if(e.target.id==='client-search'){ui.search=e.target.value;paint({focusSearch:true})}});
document.addEventListener('submit',async e=>{let f=e.target,formId=f.getAttribute('id');if(!['new-client-form','new-plan-form','new-appt-form','credit-form','message-form','service-form','staff-login-form','staff-client-form'].includes(formId))return;e.preventDefault();let x=Object.fromEntries(new FormData(f).entries());if(formId==='staff-login-form'){const r=await api('/api/v1/auth/login',{method:'POST',body:JSON.stringify({email:String(x.email||'').trim(),password:String(x.password||'')})});if(!r.ok||!r.j||!r.j.data){toast((r.j&&r.j.error&&r.j.error.message)||B('Sign in failed.','No se pudo iniciar sesion.'));return}if(await probeSession()){close();paint();toast(B('Signed in: live staging records.','Sesion iniciada: registros reales de staging.'))}else{try{await api('/api/v1/auth/logout',{method:'POST'})}catch(_){}toast(B('This account has no staff role.','Esta cuenta no tiene rol de equipo.'))}return}if(formId==='staff-client-form'){const r=await api('/api/v1/staff/clients',{method:'POST',body:JSON.stringify({email:String(x.email||'').trim(),password:String(x.password||''),display_name:String(x.name||'').trim()})});if(!r.ok){toast((r.j&&r.j.error&&r.j.error.message)||B('Could not create customer.','No se pudo crear el cliente.'));return}await refreshLiveClients();close();paint();toast(B('Staging customer created.','Cliente de staging creado.'));return}if(formId==='new-client-form'){if(data.clients.some(c=>c.name.toLowerCase()===x.name.trim().toLowerCase())){toast('Choose another fictional name.','Elige otro nombre ficticio.');return}const c={id:'c'+Date.now(),name:x.name.trim(),email:'sample@example.test',status:'active',tier:x.tier,plan:x.tier==='guided'?'Balanced 28-Day':'28-Day Digital Menu',menu:'review',credits:0,household:Math.max(1,Math.min(12,Number(x.household)||1)),skill:'Comfortable',time:30,budget:100,store:'Undecided',lang:x.lang,last:'—',introUsed:false};data.clients.unshift(c);close();navigate('clients');toast('Fictional client added locally.','Cliente ficticio agregado localmente.');return}
if(formId==='new-plan-form'){let p={id:'p'+Date.now(),client:x.client,status:'review',source:'ai',updated:dateToday(),note:String(x.note||'Review recipe suitability and household constraints.').trim().slice(0,250),blocked:false,meals:['r2','r1','r3','r4','r7','r6','r5']};data.plans.unshift(p);client(x.client).menu='review';ui.planFilter='review';close();navigate('plans');toast('Illustrative draft created; professional review required.','Borrador de ejemplo creado; requiere revisión profesional.');return}
if(formId==='new-appt-form'){let c=client(x.client);let kind=x.type,mins=kind==='intro'?15:Number(x.duration),needed=kind==='intro'?0:Math.ceil(mins/30);if(!c)return;if(kind==='paid'&&c.tier!=='guided'){toast('A paid consultation package is required in this demo.','Se necesita un paquete de consultas pagadas en esta demo.');return}if(needed>available(c)){toast('Not enough unreserved credits.','No hay suficientes créditos disponibles.');return}if(kind==='intro'&&(c.introUsed||data.appointments.some(a=>a.client===c.id&&a.type==='intro'&&a.status==='scheduled'))){toast('Free introduction is already used or scheduled.','La presentación gratuita ya se usó o se programó.');return}if(data.appointments.some(a=>a.status==='scheduled'&&a.date===x.date&&Math.abs(Number(a.time.slice(0,2))*60+Number(a.time.slice(3))-Number(x.time.slice(0,2))*60-Number(x.time.slice(3)))<Math.max(a.duration,mins))){toast('That time overlaps another demo appointment.','Ese horario coincide con otra cita de prueba.');return}data.appointments.push({id:'a'+Date.now(),client:c.id,date:x.date,time:x.time,duration:mins,type:kind,status:'scheduled'});audit('appt-scheduled',c.id);close();navigate('appointments');toast('Demo session reserved; nobody was notified.','Consulta reservada en demo; nadie recibió notificación.');return}
if(formId==='credit-form'){let c=client(x.client),n=Math.trunc(Number(x.amount));if(!c||!Number.isFinite(n)||n===0||Math.abs(n)>20){toast('Enter a nonzero change between -20 and +20.','Ingresa un cambio entre -20 y +20 distinto de cero.');return}if(c.credits+n<holds(c.id)){toast('Cannot reduce below credits already reserved.','No puedes reducir créditos ya reservados.');return}c.credits+=n;data.ledger.unshift({client:c.id,kind:'adjustment',amount:n,desc:x.reason,date:dateToday()});ui.creditClient=c.id;audit('credits-adjusted',c.id);close();toast('Credit ledger updated locally.','Registro de créditos actualizado localmente.');return}
if(formId==='service-form'){let p=data.packages.find(z=>z.id===x.id);if(!p)return;p.credits=Math.max(0,Math.min(24,Math.trunc(Number(x.credits)||0)));close();toast('Demo package updated.','Paquete de prueba actualizado.');return}
if(formId==='message-form'){let m=data.messages.find(m=>m.id===ui.messageId),msg=(x.message||'').trim();if(!m||!msg)return;m.items.push({who:'staff',text:msg,time:B('Just now','Ahora mismo')});m.unread=false;paint();toast('Demo reply added locally; nothing sent.','Respuesta agregada en demo; no se envió.');return}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&(ui.modal||ui.detail||ui.liveDetail))close()});
